"""Plot every accepted fixed/adaptive process pair, without fitting or exclusions."""
import hashlib
import json
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
AUDIT = PHASE / "comparison-v2/audit.json"
EXPECTED_AUDIT_SHA256 = "9ae4f85990d95aef7f74f0733c17883f3a19874ea1ef32fb2a7607c34bde49fa"
assert hashlib.sha256(AUDIT.read_bytes()).hexdigest() == EXPECTED_AUDIT_SHA256
data = json.loads(AUDIT.read_text())
assert data["complete"] and data["counts"]["jvms"] == 54
assert data["allResultRouteAndCleanupGatesPassed"]

fixtures = ["early-cold-hot", "late-cold-hot", "warm-cycle-8192"]
labels = ["Early 64-key repetition\nNo-growth control",
          "Late 64-key repetition\nAvoidable-growth hypothesis",
          "8,192-key cycle\nLarger working set"]
metrics = [("totalNs", "Whole-query elapsed time"),
           ("callerCpuTailNs", "Tail caller CPU"),
           ("callerAllocatedTailBytes", "Tail caller allocation")]
selected = {c["fixture"]: c for c in data["comparisons"]
            if c["candidate"] == "fixed" and c["comparator"] == "adaptive"}
colors = ["#2768A4", "#008675", "#B15A23"]
offsets = [-0.105, -0.063, -0.021, 0.021, 0.063, 0.105]
fig, axes = plt.subplots(1, 3, figsize=(13.4, 5.0), sharey=True)
for axis, (metric, title) in zip(axes, metrics):
    axis.axvline(1.0, color="#4B5563", linestyle="--", linewidth=1.0, zorder=0)
    for row, fixture in enumerate(fixtures):
        summary = selected[fixture]["primary"][metric]
        pairs = summary["pairedRatios"]
        assert len(pairs) == summary["definedPairs"] == 6
        axis.scatter(pairs, [row + offset for offset in offsets], s=42,
                     c=colors[row], alpha=0.85, edgecolors="white", linewidth=0.5)
        median = summary["medianRatio"]
        axis.scatter([median], [row], marker="D", s=68, c="#17212B",
                     edgecolors="white", linewidth=0.8, zorder=4)
        axis.annotate(f"{median:.3f}", (median, row), xytext=(0, 16),
                      textcoords="offset points", ha="center", fontsize=10,
                      color="#17212B", fontweight="bold")
    axis.set_xscale("log")
    axis.set_xlim(0.43, 2.6)
    axis.set_xticks([0.5, 0.75, 1.0, 1.5, 2.0, 2.5],
                   ["0.50", "0.75", "1.00", "1.50", "2.00", "2.50"])
    axis.minorticks_off()
    axis.set_ylim(2.5, -0.55)
    axis.set_title(title, fontsize=12, pad=15, fontweight="bold")
    axis.set_xlabel("Fixed / adaptive ratio", fontsize=10, labelpad=9)
    axis.grid(axis="x", color="#E5E7EB", linewidth=0.6)
    axis.set_axisbelow(True)
    axis.tick_params(axis="both", length=0, pad=7, labelsize=9)
    for spine in axis.spines.values():
        spine.set_visible(False)
axes[0].set_yticks(range(3), labels, fontsize=10)
fig.suptitle("Fixed capacity: consistent allocation effects, variable timing",
             x=0.02, ha="left", y=0.985, fontsize=16, fontweight="bold", color="#17212B")
fig.legend(handles=[Line2D([], [], marker="o", linestyle="", color="#5E7992",
                           label="One same-round JVM pair", markersize=6),
                    Line2D([], [], marker="D", linestyle="", color="#17212B",
                           label="Median of six paired ratios", markersize=6)],
           loc="lower left", bbox_to_anchor=(0.017, 0.065), ncol=2,
           frameon=False, fontsize=10)
fig.text(0.02, 0.025,
         "Each JVM contributes the median of its five measured queries. Every pair is shown. "
         "Below 1.00 favors fixed for that metric. Logarithmic axes; no confidence interval is implied.",
         fontsize=9, color="#4B5563")
fig.subplots_adjust(left=0.205, right=0.985, top=0.80, bottom=0.25, wspace=0.20)
outputs = []
for suffix in ("png", "svg", "pdf"):
    destination = HERE / ("fixed-adaptive-pairs." + suffix)
    if destination.exists():
        raise FileExistsError(destination)
    fig.savefig(destination, dpi=180, facecolor="white")
    outputs.append({"path": destination.name, "bytes": destination.stat().st_size,
                    "sha256": hashlib.sha256(destination.read_bytes()).hexdigest()})
plt.close(fig)
receipt = {"auditSha256": EXPECTED_AUDIT_SHA256, "plottedProcessPairs": 18,
           "metrics": [m[0] for m in metrics], "excludedPairs": 0,
           "modelFitsOrConfidenceIntervals": False, "outputs": outputs}
with (HERE / "plot-verification.json").open("x") as stream:
    json.dump(receipt, stream, indent=2, sort_keys=True)
    stream.write("\n")
print(json.dumps(receipt))
